// 원문VM출력으로대조한fixture. 실행은root담당.
use super::*;
use std::collections::BTreeMap;
struct Fixture(BTreeMap<(u64,u8),u64>);
impl Memory for Fixture{fn read(&mut self,a:u64,w:u8)->Result<u64,&'static str>{self.0.get(&(a,w)).copied().ok_or("MISSING_FIELD")}}
#[test]fn iterator_empty_cursor_no_write(){
let mut m=Fixture([((100794376u64,8u8),0u64),((100794384u64,8u8),0u64)].into_iter().collect());let e=evaluate(39,[100728832u64,100794368u64,100859904u64,0u64],&mut m).unwrap();assert_eq!(e.expected,100728832u64);assert_eq!(e.mask,u64::MAX);assert_eq!(e.output_fields,vec![(100728832u64,8u8,0u64)]);
let mut m=Fixture([((100794376u64,8u8),1u64),((100794384u64,8u8),1u64)].into_iter().collect());let e=evaluate(39,[100728832u64,100794368u64,100859904u64,0u64],&mut m).unwrap();assert_eq!(e.expected,100728832u64);assert_eq!(e.mask,u64::MAX);assert_eq!(e.output_fields,vec![(100728832u64,8u8,0u64)]);
let mut m=Fixture([((100794376u64,8u8),10u64),((100794384u64,8u8),10u64)].into_iter().collect());let e=evaluate(39,[100728832u64,100794368u64,100859904u64,0u64],&mut m).unwrap();assert_eq!(e.expected,100728832u64);assert_eq!(e.mask,u64::MAX);assert_eq!(e.output_fields,vec![(100728832u64,8u8,0u64)]);
let mut m=Fixture([((100794376u64,8u8),18446744073709551615u64),((100794384u64,8u8),18446744073709551615u64)].into_iter().collect());let e=evaluate(39,[100728832u64,100794368u64,100859904u64,0u64],&mut m).unwrap();assert_eq!(e.expected,100728832u64);assert_eq!(e.mask,u64::MAX);assert_eq!(e.output_fields,vec![(100728832u64,8u8,0u64)]);
}
